    sell_book = []  # List of (price, arrival_time, id, qty) for resting sells
    arrival_counter = 0
    order_status = {}  # Track status of orders: id -> {'qty': remaining, 'arrival_time': time, 'cancelled': bool}

    for order in orders:
        arrival_counter += 1

        if order[0] == 'cancel':
            cancel_id = order[1]
            if cancel_id in order_status and not order_status[cancel_id]['cancelled']:
                order_status[cancel_id]['cancelled'] = True
                # Remove from books
                buy_book[:] = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != cancel_id]
                sell_book[:] = [(p, t, oid, q) for p, t, oid, q in sell_book if oid != cancel_id]

